import './PasswordProtected.css';
import './Home.css';
import React, { useState, useEffect } from 'react';
import { db, analytics, logEvent } from '../firebase';
import { doc, getDoc } from 'firebase/firestore';

const PasswordProtected = ({ children }) => {
    const [input, setInput] = useState('');
    const [error, setError] = useState('');
    const [storedHash, setStoredHash] = useState('');
    const [unlocked, setUnlocked] = useState(false);

    useEffect(() => {
        const fetchHash = async () => {
            try {
                const docRef = doc(db, 'secrets', 'case-study-a');
                const docSnap = await getDoc(docRef);
                if (docSnap.exists()) {
                    setStoredHash(docSnap.data().passwordHash);
                } else {
                    setError("Case study not found.");
                }
            } catch (err) {
                console.error('Error fetching password hash:', err);
                setError("Error connecting to database.");
            }
        };

        fetchHash();
        logEvent(analytics, 'case_study_password_page_viewed');
    }, []);

    const handleCheckPassword = async (e) => {
        e.preventDefault();

        const encoder = new TextEncoder();
        const data = encoder.encode(input);
        const hashBuffer = await crypto.subtle.digest('SHA-256', data);
        const hashArray = Array.from(new Uint8Array(hashBuffer));
        const inputHash = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');

        if (inputHash === storedHash) {
            setUnlocked(true);
            logEvent(analytics, 'case_study_unlocked');
        } else {
            setError("Incorrect password");
            logEvent(analytics, 'case_study_password_failed');
        }
    };

    if (unlocked) return <>{children}</>;

    return (
        <div className="password-wrapper container">
            <h2>This case study is password protected</h2>
            <form onSubmit={handleCheckPassword} className="password-form">
                <input
                    className="password-input"
                    type="password"
                    placeholder="Enter password"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                />
                <button className="password-button" type="submit">Enter</button>
            </form>
            {error && <p className="error-message">{error}</p>}
        </div>
    );
};

export default PasswordProtected;
